// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/*

    _  __  ______
   | |/ / |  ____|
   | ' /  | |__
   |  <   |  __|
   | . \  | |
   |_|\_\ |_|

    KOIN FORGE
    Clean ETH token launches forged for developers.

    Web:     https://koinforge.xyz
    X:       https://x.com/koinforgedev
    Deploys: https://t.me/KoinForge_deploys

    0% token tax
    0 pool fee
    no hooks
    no creator rewards
    2% max buy per transaction

*/

interface IERC20RescueTarget {
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @title DevLaunchERC20
/// @notice Fixed-supply ERC20 for no-tax Uniswap v4 launches with optional max-buy and delayed open trading.
/// @dev No mint, no blacklist, no pause, no tax, no owner authority. Max-buy applies only to buys from marked v4/router sources.
contract DevLaunchERC20 {
    string private _name;
    string private _symbol;
    string public projectInfo;

    uint8 public constant decimals = 18;
    uint256 public constant MAX_BUY_BPS = 200;
    uint256 public constant BPS = 10_000;
    string public constant contractVersion = "KoinForge DevLaunchERC20 v3";
    string public constant forgeName = "Koin Forge";
    string public constant forgeWeb = "https://koinforge.xyz";
    string public constant forgeDeploys = "https://t.me/KoinForge_deploys";
    string public constant forgeX = "https://x.com/koinforgedev";

    address public immutable launcher;
    address public immutable rescueReceiver;
    bool public immutable maxBuyEnabled;
    uint256 public immutable maxBuyAmount;
    bool public tradingOpen;
    uint256 public totalSupply;

    mapping(address account => uint256) public balanceOf;
    mapping(address owner => mapping(address spender => uint256)) public allowance;
    mapping(address account => bool) public isMaxBuySource;
    mapping(address account => bool) public isMaxBuyExempt;
    mapping(address account => bool) public isTradingExempt;

    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event ETHReceived(address indexed sender, uint256 amount);
    event ETHRescued(address indexed receiver, uint256 amount);
    event ERC20Rescued(address indexed token, address indexed receiver, uint256 amount);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event TradingOpened(address indexed token, address indexed launcher);
    event MaxBuySourceSet(address indexed account, bool enabled);
    event MaxBuyExemptSet(address indexed account, bool exempt);
    event TradingExemptSet(address indexed account, bool exempt);

    error InsufficientAllowance();
    error InsufficientBalance();
    error InvalidAddress();
    error NotLauncher();
    error NotRescueReceiver();
    error RescueTransferFailed();
    error TradingAlreadyOpen();
    error TradingClosed();
    error MaxBuyExceeded(address buyer, uint256 amount, uint256 maxBuyAmount);

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 supply_,
        address initialHolder_,
        address rescueReceiver_,
        string memory projectInfo_,
        bool maxBuyEnabled_,
        bool tradingOpenOnDeploy_,
        address[] memory maxBuySources_,
        address[] memory maxBuyExemptions_,
        address[] memory tradingExemptions_
    ) {
        if (bytes(name_).length == 0 || bytes(symbol_).length == 0) revert InvalidAddress();
        if (initialHolder_ == address(0) || rescueReceiver_ == address(0)) revert InvalidAddress();
        if (supply_ == 0) revert InvalidAddress();

        _name = name_;
        _symbol = symbol_;
        launcher = msg.sender;
        rescueReceiver = rescueReceiver_;
        projectInfo = projectInfo_;
        maxBuyEnabled = maxBuyEnabled_;
        tradingOpen = tradingOpenOnDeploy_;

        totalSupply = supply_;
        maxBuyAmount = (supply_ * MAX_BUY_BPS) / BPS;
        _setMaxBuyExempt(initialHolder_, true);
        _setMaxBuyExempt(rescueReceiver_, true);
        _setMaxBuyExempt(address(this), true);
        _setTradingExempt(initialHolder_, true);
        _setTradingExempt(rescueReceiver_, true);
        _setTradingExempt(address(this), true);
        for (uint256 index = 0; index < maxBuySources_.length; index += 1) {
            _setMaxBuySource(maxBuySources_[index], true);
        }
        for (uint256 index = 0; index < maxBuyExemptions_.length; index += 1) {
            _setMaxBuyExempt(maxBuyExemptions_[index], true);
        }
        for (uint256 index = 0; index < tradingExemptions_.length; index += 1) {
            _setTradingExempt(tradingExemptions_[index], true);
        }

        balanceOf[initialHolder_] = supply_;
        emit Transfer(address(0), initialHolder_, supply_);

        // Ownership is renounced by design. Rescue permission is separate and immutable.
        emit OwnershipTransferred(msg.sender, address(0));
    }

    receive() external payable {
        emit ETHReceived(msg.sender, msg.value);
    }

    function name() external view returns (string memory) {
        return _name;
    }

    function symbol() external view returns (string memory) {
        return _symbol;
    }

    function owner() external pure returns (address) {
        return address(0);
    }

    function renounceOwnership() external pure returns (bool) {
        return true;
    }

    function openTrading() external returns (bool) {
        if (msg.sender != launcher) revert NotLauncher();
        if (tradingOpen) revert TradingAlreadyOpen();
        tradingOpen = true;
        emit TradingOpened(address(this), launcher);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        _approve(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 currentAllowance = allowance[from][msg.sender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < value) revert InsufficientAllowance();
            unchecked {
                allowance[from][msg.sender] = currentAllowance - value;
            }
            emit Approval(from, msg.sender, allowance[from][msg.sender]);
        }

        _transfer(from, to, value);
        return true;
    }

    function increaseAllowance(address spender, uint256 addedValue) external returns (bool) {
        _approve(msg.sender, spender, allowance[msg.sender][spender] + addedValue);
        return true;
    }

    function decreaseAllowance(address spender, uint256 subtractedValue) external returns (bool) {
        uint256 currentAllowance = allowance[msg.sender][spender];
        if (currentAllowance < subtractedValue) revert InsufficientAllowance();
        unchecked {
            _approve(msg.sender, spender, currentAllowance - subtractedValue);
        }
        return true;
    }

    function burn(uint256 value) external {
        _burn(msg.sender, value);
    }

    function burnFrom(address account, uint256 value) external {
        uint256 currentAllowance = allowance[account][msg.sender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < value) revert InsufficientAllowance();
            unchecked {
                allowance[account][msg.sender] = currentAllowance - value;
            }
            emit Approval(account, msg.sender, allowance[account][msg.sender]);
        }
        _burn(account, value);
    }

    function rescueETH(uint256 amount) external returns (uint256 rescued) {
        _onlyRescueReceiver();
        rescued = amount == 0 ? address(this).balance : amount;
        (bool ok,) = rescueReceiver.call{value: rescued}("");
        if (!ok) revert RescueTransferFailed();
        emit ETHRescued(rescueReceiver, rescued);
    }

    function rescueERC20(address token, uint256 amount) external returns (uint256 rescued) {
        _onlyRescueReceiver();
        if (token == address(0)) revert InvalidAddress();

        rescued = amount == 0 ? IERC20RescueTarget(token).balanceOf(address(this)) : amount;
        bool ok = IERC20RescueTarget(token).transfer(rescueReceiver, rescued);
        if (!ok) revert RescueTransferFailed();
        emit ERC20Rescued(token, rescueReceiver, rescued);
    }

    function _transfer(address from, address to, uint256 value) private {
        if (from == address(0) || to == address(0)) revert InvalidAddress();

        uint256 fromBalance = balanceOf[from];
        if (fromBalance < value) revert InsufficientBalance();
        if (from == to) {
            emit Transfer(from, to, value);
            return;
        }

        uint256 nextToBalance = balanceOf[to] + value;
        _enforceTradingOpen(from, to);
        _enforceMaxBuy(from, to, value);

        unchecked {
            balanceOf[from] = fromBalance - value;
            balanceOf[to] = nextToBalance;
        }

        emit Transfer(from, to, value);
    }

    function _burn(address account, uint256 value) private {
        if (account == address(0)) revert InvalidAddress();

        uint256 accountBalance = balanceOf[account];
        if (accountBalance < value) revert InsufficientBalance();

        unchecked {
            balanceOf[account] = accountBalance - value;
            totalSupply -= value;
        }

        emit Transfer(account, address(0), value);
    }

    function _approve(address owner_, address spender, uint256 value) private {
        if (owner_ == address(0) || spender == address(0)) revert InvalidAddress();
        allowance[owner_][spender] = value;
        emit Approval(owner_, spender, value);
    }

    function _onlyRescueReceiver() private view {
        if (msg.sender != rescueReceiver) revert NotRescueReceiver();
    }

    function _enforceTradingOpen(address from, address to) private view {
        if (tradingOpen) return;
        if (isTradingExempt[from] && isTradingExempt[to]) return;
        revert TradingClosed();
    }

    function _enforceMaxBuy(address from, address to, uint256 amount) private view {
        if (!maxBuyEnabled) return;
        if (!isMaxBuySource[from]) return;
        if (isMaxBuyExempt[to]) return;
        if (amount > maxBuyAmount) revert MaxBuyExceeded(to, amount, maxBuyAmount);
    }

    function _setMaxBuySource(address account, bool enabled) private {
        if (account == address(0)) revert InvalidAddress();
        isMaxBuySource[account] = enabled;
        emit MaxBuySourceSet(account, enabled);
    }

    function _setMaxBuyExempt(address account, bool exempt) private {
        if (account == address(0)) revert InvalidAddress();
        isMaxBuyExempt[account] = exempt;
        emit MaxBuyExemptSet(account, exempt);
    }

    function _setTradingExempt(address account, bool exempt) private {
        if (account == address(0)) revert InvalidAddress();
        isTradingExempt[account] = exempt;
        emit TradingExemptSet(account, exempt);
    }
}

