// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {DevLaunchERC20} from "./DevLaunchERC20.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {IPositionManager} from "@uniswap/v4-periphery/src/interfaces/IPositionManager.sol";
import {Actions} from "@uniswap/v4-periphery/src/libraries/Actions.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";

interface IERC20LauncherRescueTarget {
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IAllowanceTransferMinimal {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}

interface IPositionManagerState {
    function poolManager() external view returns (address);
}

/// @title DevLaunchLauncher
/// @notice CREATE2 launcher for zero-fee, no-hook Uniswap v4 token launches.
/// @dev Instant launches mint 0 ETH + 100% token supply liquidity immediately. Open-later launches deploy first, then create/burn LP when trading is opened.
contract DevLaunchLauncher {
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public constant NATIVE = address(0);
    uint24 public constant POOL_FEE = 0;
    int24 public constant TICK_SPACING = 1;
    uint256 public constant MIN_SUPPLY = 1 ether;
    uint256 public constant MAX_SUPPLY = 100_000_000_000 ether;
    uint256 public constant Q192 = 2 ** 192;
    uint256 public constant MAX_REFERRAL_BPS = 2500;
    uint256 public constant BPS = 10_000;

    IPositionManager public immutable positionManager;
    IAllowanceTransferMinimal public immutable permit2;
    address public immutable poolManager;
    address public immutable universalRouter;
    address public immutable rescueReceiver;
    address public immutable botFeeReceiver;
    address public immutable referralTreasury;
    uint256 public immutable flatFeeWei;
    mapping(address token => address opener) public pendingTradingOpener;
    mapping(address token => uint256 virtualEthWei) public pendingTradingVirtualEthWei;

    event Launched(
        address indexed token,
        bytes32 indexed salt,
        uint256 indexed tokenId,
        address launcher,
        uint256 supply,
        uint256 virtualEthWei,
        uint160 sqrtPriceX96,
        int24 tickLower,
        int24 tickUpper,
        int24 tickSpacing,
        uint256 liquidity,
        uint256 referralBps,
        bool maxBuyEnabled,
        bool tradingOpen
    );
    event TradingPending(address indexed token, address indexed opener);
    event TradingOpened(address indexed token, address indexed opener);
    event PendingLaunchCreated(
        address indexed token, bytes32 indexed salt, address indexed opener, uint256 supply, uint256 virtualEthWei
    );
    event LiquidityActivated(
        address indexed token,
        uint256 indexed tokenId,
        address indexed opener,
        uint256 supply,
        uint256 virtualEthWei,
        uint160 sqrtPriceX96,
        int24 tickLower,
        int24 tickUpper,
        int24 tickSpacing,
        uint256 liquidity
    );
    event ETHRescued(address indexed receiver, uint256 amount);
    event ERC20Rescued(address indexed token, address indexed receiver, uint256 amount);

    error InvalidAddress();
    error InvalidAmount();
    error InvalidOpener();
    error InvalidTicks();
    error NotPendingTokenOpener();
    error FeeTooLow();
    error RescueTransferFailed();
    error TokenTransferFailed();
    error TokenLiquidityNotFull();

    struct LaunchParams {
        string name;
        string symbol;
        uint256 supply;
        string projectInfo;
        bytes32 salt;
        uint256 virtualEthWei;
        uint256 referralBps;
        address opener;
        bool maxBuyEnabled;
        bool startTradingOpen;
    }

    struct LaunchMath {
        uint160 sqrtPriceX96;
        int24 tickLower;
        int24 tickUpper;
        int24 tickSpacing;
        uint128 liquidity;
    }

    constructor(
        address positionManager_,
        address permit2_,
        address universalRouter_,
        address botFeeReceiver_,
        address referralTreasury_,
        uint256 flatFeeWei_
    ) {
        if (
            positionManager_ == address(0) || permit2_ == address(0) || universalRouter_ == address(0)
                || botFeeReceiver_ == address(0) || referralTreasury_ == address(0)
        ) revert InvalidAddress();

        positionManager = IPositionManager(positionManager_);
        permit2 = IAllowanceTransferMinimal(permit2_);
        poolManager = IPositionManagerState(positionManager_).poolManager();
        if (poolManager == address(0)) revert InvalidAddress();
        universalRouter = universalRouter_;
        rescueReceiver = botFeeReceiver_;
        botFeeReceiver = botFeeReceiver_;
        referralTreasury = referralTreasury_;
        flatFeeWei = flatFeeWei_;
    }

    receive() external payable {}

    function launch(LaunchParams calldata params) external payable returns (address token, uint256 tokenId) {
        LaunchMath memory math = quoteLaunch(params.supply, params.virtualEthWei);
        if (msg.value < flatFeeWei) revert FeeTooLow();
        if (!params.startTradingOpen && params.opener == address(0)) revert InvalidOpener();

        token = address(
            new DevLaunchERC20{salt: params.salt}(
                params.name,
                params.symbol,
                params.supply,
                address(this),
                rescueReceiver,
                _brandProjectInfo(params.projectInfo, params.maxBuyEnabled),
                params.maxBuyEnabled,
                params.startTradingOpen,
                _maxBuySources(),
                _maxBuyExemptions(),
                _tradingExemptions()
            )
        );

        if (params.startTradingOpen) {
            tokenId = _activateLiquidity(token, params.supply, math);
        } else {
            pendingTradingOpener[token] = params.opener;
            pendingTradingVirtualEthWei[token] = params.virtualEthWei;
            emit TradingPending(token, params.opener);
            emit PendingLaunchCreated(token, params.salt, params.opener, params.supply, params.virtualEthWei);
        }

        _collectFee(params.referralBps);
        _refundDust();

        if (params.startTradingOpen) {
            emit Launched(
                token,
                params.salt,
                tokenId,
                msg.sender,
                params.supply,
                params.virtualEthWei,
                math.sqrtPriceX96,
                math.tickLower,
                math.tickUpper,
                math.tickSpacing,
                math.liquidity,
                params.referralBps,
                params.maxBuyEnabled,
                true
            );
        }
    }

    function openTrading(address token) external returns (bool) {
        address opener = pendingTradingOpener[token];
        uint256 virtualEthWei = pendingTradingVirtualEthWei[token];
        if (opener == address(0) || msg.sender != opener) revert NotPendingTokenOpener();
        LaunchMath memory math = quoteLaunch(DevLaunchERC20(payable(token)).totalSupply(), virtualEthWei);
        uint256 tokenId = _activateLiquidity(token, DevLaunchERC20(payable(token)).totalSupply(), math);
        delete pendingTradingOpener[token];
        delete pendingTradingVirtualEthWei[token];
        bool ok = DevLaunchERC20(payable(token)).openTrading();
        if (ok) {
            emit LiquidityActivated(
                token,
                tokenId,
                msg.sender,
                DevLaunchERC20(payable(token)).totalSupply(),
                virtualEthWei,
                math.sqrtPriceX96,
                math.tickLower,
                math.tickUpper,
                math.tickSpacing,
                math.liquidity
            );
            emit TradingOpened(token, msg.sender);
        }
        return ok;
    }

    function quoteLaunch(uint256 supply, uint256 virtualEthWei) public pure returns (LaunchMath memory math) {
        if (supply < MIN_SUPPLY || supply > MAX_SUPPLY || supply > type(uint128).max) revert InvalidAmount();
        if (!_allowedTier(virtualEthWei)) revert InvalidAmount();

        math.sqrtPriceX96 = _sqrtPriceX96(supply, virtualEthWei);
        int24 currentTick = TickMath.getTickAtSqrtPrice(math.sqrtPriceX96);
        math.tickSpacing = TICK_SPACING;
        math.tickUpper = _floorUsableTick(currentTick, TICK_SPACING);
        math.tickLower = TickMath.minUsableTick(TICK_SPACING);
        if (math.tickLower >= math.tickUpper) revert InvalidTicks();
        math.liquidity = LiquidityAmounts.getLiquidityForAmount1(
            TickMath.getSqrtPriceAtTick(math.tickLower), TickMath.getSqrtPriceAtTick(math.tickUpper), supply
        );
        if (math.liquidity == 0) revert InvalidAmount();
    }

    function computeTokenAddress(
        string calldata name,
        string calldata symbol,
        uint256 supply,
        string calldata projectInfo,
        bytes32 salt,
        bool maxBuyEnabled,
        bool startTradingOpen
    ) external view returns (address) {
        bytes32 initCodeHash = keccak256(
            abi.encodePacked(
                type(DevLaunchERC20).creationCode,
                abi.encode(
                    name,
                    symbol,
                    supply,
                    address(this),
                    rescueReceiver,
                    _brandProjectInfo(projectInfo, maxBuyEnabled),
                    maxBuyEnabled,
                    startTradingOpen,
                    _maxBuySources(),
                    _maxBuyExemptions(),
                    _tradingExemptions()
                )
            )
        );
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, initCodeHash)))));
    }

    function rescueETH(uint256 amount) external returns (uint256 rescued) {
        rescued = amount == 0 ? address(this).balance : amount;
        (bool ok,) = rescueReceiver.call{value: rescued}("");
        if (!ok) revert RescueTransferFailed();
        emit ETHRescued(rescueReceiver, rescued);
    }

    function rescueERC20(address token, uint256 amount) external returns (uint256 rescued) {
        if (token == address(0)) revert InvalidAddress();
        rescued = amount == 0 ? IERC20LauncherRescueTarget(token).balanceOf(address(this)) : amount;
        bool ok = IERC20LauncherRescueTarget(token).transfer(rescueReceiver, rescued);
        if (!ok) revert TokenTransferFailed();
        emit ERC20Rescued(token, rescueReceiver, rescued);
    }

    function _approveForPositionManager(address token, uint256 amount) private {
        // Approve Permit2 at ERC20 layer, then approve PositionManager inside Permit2.
        (bool approved,) =
            token.call(abi.encodeWithSignature("approve(address,uint256)", address(permit2), type(uint256).max));
        if (!approved) revert TokenTransferFailed();
        permit2.approve(token, address(positionManager), uint160(amount), type(uint48).max);
    }

    function _sendTokenDustToDead(address token, uint256 supply) private {
        uint256 dust = IERC20LauncherRescueTarget(token).balanceOf(address(this));
        if (dust == 0) return;
        uint256 maxDust = supply / 1_000_000;
        if (maxDust < 1_000) maxDust = 1_000;
        if (dust > maxDust) revert TokenLiquidityNotFull();
        bool ok = IERC20LauncherRescueTarget(token).transfer(DEAD, dust);
        if (!ok) revert TokenTransferFailed();
    }

    function _activateLiquidity(address token, uint256 supply, LaunchMath memory math) private returns (uint256 tokenId) {
        PoolKey memory key = PoolKey({
            currency0: Currency.wrap(NATIVE),
            currency1: Currency.wrap(token),
            fee: POOL_FEE,
            tickSpacing: math.tickSpacing,
            hooks: IHooks(address(0))
        });

        positionManager.initializePool(key, math.sqrtPriceX96);

        _approveForPositionManager(token, supply);

        tokenId = positionManager.nextTokenId();
        bytes memory actions = abi.encodePacked(bytes1(uint8(Actions.MINT_POSITION)), bytes1(uint8(Actions.SETTLE_PAIR)));
        bytes[] memory mintParams = new bytes[](2);
        mintParams[0] = abi.encode(
            key,
            math.tickLower,
            math.tickUpper,
            math.liquidity,
            uint128(0),
            uint128(supply),
            DEAD,
            bytes("")
        );
        mintParams[1] = abi.encode(key.currency0, key.currency1);

        positionManager.modifyLiquidities(abi.encode(actions, mintParams), block.timestamp);
        _sendTokenDustToDead(token, supply);
    }

    function _collectFee(uint256 referralBps) private {
        if (flatFeeWei == 0) return;
        if (referralBps > 0) {
            if (referralBps > MAX_REFERRAL_BPS) revert InvalidAmount();
            uint256 referralAmount = (flatFeeWei * referralBps) / BPS;
            uint256 botAmount = flatFeeWei - referralAmount;
            _sendETH(botFeeReceiver, botAmount);
            _sendETH(referralTreasury, referralAmount);
        } else {
            _sendETH(botFeeReceiver, flatFeeWei);
        }
    }

    function _refundDust() private {
        uint256 dust = address(this).balance;
        if (dust > 0) _sendETH(msg.sender, dust);
    }

    function _sendETH(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok,) = to.call{value: amount}("");
        if (!ok) revert RescueTransferFailed();
    }

    function _allowedTier(uint256 virtualEthWei) private pure returns (bool) {
        return virtualEthWei == 500_000_000_000_000_000 || virtualEthWei == 1 ether || virtualEthWei == 2 ether
            || virtualEthWei == 5 ether || virtualEthWei == 10 ether;
    }

    function _sqrtPriceX96(uint256 supply, uint256 virtualEthWei) private pure returns (uint160) {
        uint256 ratioX192 = FullMath.mulDiv(supply, Q192, virtualEthWei);
        uint256 sqrtRatio = _sqrt(ratioX192);
        if (sqrtRatio == 0 || sqrtRatio > type(uint160).max) revert InvalidAmount();
        return uint160(sqrtRatio);
    }

    function _floorUsableTick(int24 tick, int24 tickSpacing) private pure returns (int24) {
        int24 compressed = tick / tickSpacing;
        if (tick < 0 && tick % tickSpacing != 0) compressed--;
        return compressed * tickSpacing;
    }

    function _brandProjectInfo(string calldata projectInfo, bool maxBuyEnabled) private pure returns (string memory) {
        string memory brand = maxBuyEnabled
            ? "Koin Forge\nWeb: https://koinforge.xyz\nX: https://x.com/koinforgedev\nDeploys: https://t.me/KoinForge_deploys\nMax buy: 2% per transaction"
            : "Koin Forge\nWeb: https://koinforge.xyz\nX: https://x.com/koinforgedev\nDeploys: https://t.me/KoinForge_deploys\nMax buy: off";
        if (bytes(projectInfo).length == 0) return brand;
        return string.concat(brand, "\nProject: ", projectInfo);
    }

    function _maxBuySources() private view returns (address[] memory sources) {
        sources = new address[](3);
        sources[0] = poolManager;
        sources[1] = universalRouter;
        sources[2] = address(positionManager);
    }

    function _maxBuyExemptions() private view returns (address[] memory exemptions) {
        exemptions = new address[](8);
        exemptions[0] = address(this);
        exemptions[1] = rescueReceiver;
        exemptions[2] = referralTreasury;
        exemptions[3] = address(positionManager);
        exemptions[4] = address(permit2);
        exemptions[5] = poolManager;
        exemptions[6] = universalRouter;
        exemptions[7] = DEAD;
    }

    function _tradingExemptions() private view returns (address[] memory exemptions) {
        exemptions = new address[](8);
        exemptions[0] = address(this);
        exemptions[1] = rescueReceiver;
        exemptions[2] = referralTreasury;
        exemptions[3] = address(positionManager);
        exemptions[4] = address(permit2);
        exemptions[5] = poolManager;
        exemptions[6] = universalRouter;
        exemptions[7] = DEAD;
    }

    function _sqrt(uint256 x) private pure returns (uint256 z) {
        if (x == 0) return 0;
        uint256 y = x;
        z = 1;
        if (y >= 2 ** 128) {
            y >>= 128;
            z <<= 64;
        }
        if (y >= 2 ** 64) {
            y >>= 64;
            z <<= 32;
        }
        if (y >= 2 ** 32) {
            y >>= 32;
            z <<= 16;
        }
        if (y >= 2 ** 16) {
            y >>= 16;
            z <<= 8;
        }
        if (y >= 2 ** 8) {
            y >>= 8;
            z <<= 4;
        }
        if (y >= 2 ** 4) {
            y >>= 4;
            z <<= 2;
        }
        if (y >= 2 ** 2) z <<= 1;

        unchecked {
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            z = (z + x / z) >> 1;
            uint256 roundedDown = x / z;
            return z < roundedDown ? z : roundedDown;
        }
    }
}

